window.ELprob=function(l){var sk=l&&l.sk||0;if(!sk)return 20;
var y=Math.floor(sk/10000),m=Math.floor(sk/100)%100,d=sk%100;
var dep=new Date(y,m-1,d),now=new Date();now.setHours(0,0,0,0);
var days=Math.round((dep-now)/86400000);if(days<0)days=0;
/* 90 % at the nearest date easing to 20 % at the far end. Exponential rather
   than linear: an empty leg is confirmed or gone quickly, then the odds
   flatten. day 0 = 90, 7 = 73, 14 = 60, 30 = 41, 60 = 26, 120 = 21. */
var p=20+70*Math.exp(-days/25);
return Math.max(20,Math.min(90,Math.round(p)));};

(function(){
  /* The file is a snapshot, so it goes stale on its own. Drop anything that
     has already departed, and keep any "N legs available" counter honest. */
  var t=new Date();t.setHours(0,0,0,0);
  var k=t.getFullYear()*10000+(t.getMonth()+1)*100+t.getDate();
  window.EMPTY_LEGS=(window.EMPTY_LEGS||[]).filter(function(l){return (l.sk||0)>=k;});
  var n=window.EMPTY_LEGS.length;
  function paint(){
    [].forEach.call(document.querySelectorAll('.empty-update,.el-count,[data-el-count]'),
      function(e){ e.innerHTML=e.innerHTML.replace(/\d+\s+legs available/, n+' legs available'); });
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',paint);
  else paint();
})();
